const chests = drone.scanChests({ radius: 24 });
if (!chests.chests || !chests.chests.length) return { ok: false, error: 'no chest within 24m', hint: 'craft/place a chest or widen the search' };
const chest = chests.chests[0];
const moved = drone.goto({ standoffOf: { x: chest.x, y: chest.y, z: chest.z } });
if (!moved.arrived) return { ok: false, error: 'could not reach the chest', chest: chest };
const deposited = drone.depositChest({ x: chest.x, y: chest.y, z: chest.z });
return { chest: chest, deposited: deposited };
